import{_ as p,a0 as s,w as i,s as b,ao as r,I as l,x as u,a1 as e,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"每日Ubuntu小技巧 —— 禁用Ubuntu的屏幕鎖定 | LCTT x X-CMD","titleTemplate":false,"description":"每日Ubuntu小技巧 —— 禁用Ubuntu的屏幕鎖定 | LCTT (201310) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"每日Ubuntu小技巧 —— 禁用Ubuntu的屏幕鎖定 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"每日Ubuntu小技巧 —— 禁用Ubuntu的屏幕鎖定 | LCTT (201310) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201310/Daily Ubuntu Tips – Disable Ubuntu Lock Screen","title":"每日Ubuntu小技巧 —— 禁用Ubuntu的屏幕鎖定","tag":"201310","desc":""},"relativePath":"201310/Daily Ubuntu Tips – Disable Ubuntu Lock Screen.md","filePath":"[post].md"}'),o={name:"201310/Daily Ubuntu Tips – Disable Ubuntu Lock Screen.md"};function d(U,t,T,m,g,k){const n=s("Link");return i(),b("div",null,[t[11]||(t[11]=r('<h1 id="每日ubuntu小技巧-——-禁用ubuntu的屏幕鎖定" tabindex="-1">每日Ubuntu小技巧 —— 禁用Ubuntu的屏幕鎖定 <a class="header-anchor" href="#每日ubuntu小技巧-——-禁用ubuntu的屏幕鎖定" aria-label="Permalink to “每日Ubuntu小技巧 —— 禁用Ubuntu的屏幕鎖定”">​</a></h1><p>當您還是Ubuntu新手時，有一些功能您還無法馬上知道。例如，如何修改您的密碼、禁用某些功能和創建新用户帳號等。當新用户試用Ubuntu時，經常會問一個問題：如何關閉屏幕鎖定或阻止Ubuntu屏幕逐漸變暗。</p><p>這裏為Ubuntu新手準備了一些簡單技巧。這些技巧對於Ubuntu高手而言毫無新意，此教程也不是為Ubuntu高手而準備的，它們僅供Ubuntu新手學習使用。</p><p>Ubuntu被設計成幾分鐘後就自動鎖定，再次使用之前您必須輸入密碼來解鎖。如果這給您帶來了太多的麻煩，那麼您也許想要關閉這個自動鎖屏功能，而這正是下面馬上將要介紹的內容。</p><p>您計算機的自動鎖定是出於安全的原因，如果您禁用或關閉了它，您的計算機將不再被鎖定，任何可以物理接觸到您計算機的人都可以登錄並且使用它。如果對您而言，這不是什麼大問題，那麼繼續下面學習具體如何來做。</p><p>首先，登錄Ubuntu，點擊控制選項（位於菜單欄的最右邊的圖標）圖標並選擇 <strong>系統設置</strong> 。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/09/ubuntulockscreendisable.png" alt=""></p><p>接着，點擊系統設置面板裏的“亮度和鎖屏”圖標</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/09/ubuntulockscreendisable1.png" alt=""></p><p>最後，關閉“鎖定屏幕選項”。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/09/ubuntulockscreendisable2.png" alt=""></p><p>就是這樣了！如果您要重新開啓它，那麼再次點擊“鎖定屏幕選項”切換回去即可。屏幕鎖定是一個很好的特性，可以保護您的計算機，但如果您知道您的隱私或信息不會有風險，那麼您可以禁用它。</p><hr>',13)),l("p",null,[t[1]||(t[1]=u("via: ",-1)),e(n,{href:"http://www.liberiangeek.net/2013/09/daily-ubuntu-tips-disable-ubuntu-lock-screen/"},{default:a(()=>[...t[0]||(t[0]=[u("http://www.liberiangeek.net/2013/09/daily-ubuntu-tips-disable-ubuntu-lock-screen/",-1)])]),_:1})]),l("p",null,[t[4]||(t[4]=u("譯者：",-1)),e(n,{href:"https://github.com/lenky0401"},{default:a(()=>[...t[2]||(t[2]=[u("lenky0401",-1)])]),_:1}),t[5]||(t[5]=u(" 校對：",-1)),e(n,{href:"https://github.com/carolinewuyan"},{default:a(()=>[...t[3]||(t[3]=[u("Caroline",-1)])]),_:1})]),l("p",null,[t[8]||(t[8]=u("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[6]||(t[6]=[u("LCTT",-1)])]),_:1}),t[9]||(t[9]=u(" 原創翻譯，",-1)),e(n,{href:"http://linux.cn/"},{default:a(()=>[...t[7]||(t[7]=[u("Linux中國",-1)])]),_:1}),t[10]||(t[10]=u(" 榮譽推出",-1))])])}const D=p(o,[["render",d]]);export{C as __pageData,D as default};
